import pandas as pd

def consecutive_numbers(logs: pd.DataFrame) -> pd.DataFrame:
    if len(logs) < 3:
        return pd.DataFrame(columns=['ConsecutiveNums'])
    logs = logs.sort_values(by='id').reset_index(drop=True)
    logs['prev_num'] = logs['num'].shift(1)
    logs['next_num'] = logs['num'].shift(-1)
    logs['prev_id'] = logs['id'].shift(1)
    logs['next_id'] = logs['id'].shift(-1)
    match = logs[
        (logs['num'] == logs['prev_num']) &
        (logs['num'] == logs['next_num']) &
        (logs['prev_id'] == logs['id'] - 1) &
        (logs['next_id'] == logs['id'] + 1)
    ]
    return pd.DataFrame({'ConsecutiveNums': match['num'].drop_duplicates()})
